#include <string.h>
int main() {
    char s[1000];
    if (fgets(s, sizeof(s), stdin)) {
        int len = strlen(s);
        if (len > 0 && s[len-1] == '\n') s[--len] = '\0';
        for (int i = len - 1; i >= 0; i--) {
            putchar(s[i]);
        }
    }
    return 0;
}

